                        tmp_result = tmp_result or (
                            output == in_outs['outputs'][index])
                except Exception as e:
                    if debug:
                        print(f'Failed check3 exception = {e}')
                    pass

                try:
                    output_float = [float(e) for e in output]
                    gt_float = [float(e) for e in in_outs['outputs'][index]]
                    tmp_result = tmp_result or (
                        (len(output_float) == len(gt_float))
                        and np.allclose(output_float, gt_float))
                except Exception:
                    pass
                try:
                    if isinstance(output[0], list):
                        output_float = [float(e) for e in output[0]]
                        gt_float = [
                            float(e) for e in in_outs['outputs'][index][0]
                        ]
                        tmp_result = tmp_result or (
                            (len(output_float) == len(gt_float))
                            and np.allclose(output_float, gt_float))
                except Exception:
                    pass

                if tmp_result == True:
                    results.append(tmp_result)
                    continue

                if isinstance(in_outs['outputs'][index], list):
                    for tmp_index, i in enumerate(in_outs['outputs'][index]):
                        in_outs['outputs'][index][tmp_index] = set(i.split())
                else:
                    in_outs['outputs'][index] = set(
                        in_outs['outputs'][index].split())

                try:
                    tmp_result = (output == in_outs['outputs'][index])
                except Exception as e:
                    if debug:
                        print(f'Failed check4 exception = {e}')
                    continue

                if tmp_result == True:
                    results.append(tmp_result)
                    continue

                if isinstance(output, list):
                    for tmp_index, i in enumerate(output):
                        output[tmp_index] = i.split()
                    output = list(filter(len, output))
                    for tmp_index, i in enumerate(output):
                        output[tmp_index] = set(i)
                else:
                    output = output.split()
                    output = list(filter(len, output))
                    output = set(output)

                try:
                    tmp_result = (set(frozenset(s) for s in output) == set(
                        frozenset(s) for s in in_outs['outputs'][index]))
                except Exception as e:
                    if debug:
                        print(f'Failed check5 exception = {e}')

                try:
                    tmp_result = tmp_result or (
                        set(
                            frozenset(round(float(t), 3) for t in s)
                            for s in output) ==
                        set(
                            frozenset(round(float(t), 3) for t in s)
                            for s in in_outs['outputs'][index]))
                except Exception as e:
                    if debug:
                        print(f'Failed check6 exception = {e}')

                if tmp_result == True and debug:
                    print('PASSED')

                results.append(tmp_result)

                if debug:
                    nl = '\n'
                    if not isinstance(inputs, list):
                        print(
                            f"output = {output}, test outputs = {in_outs['outputs'][index]}, inputs = {inputs.replace(nl,' new-line ')}, {type(inputs)}, {output == [in_outs['outputs'][index]]}"
                        )
                    else:
                        print(
                            f"output = {output}, test outputs = {in_outs['outputs'][index]}, inputs = {inputs}, {type(inputs)}, {output == [in_outs['outputs'][index]]}"
                        )

    return results

def custom_compare_(output, ground_truth):

    if isinstance(output, list):
        output_1 = '\n'.join(output)
        if stripped_string_compare(output_1, ground_truth):
            return True

    if isinstance(output, list):
        output_2 = [o.lstrip().rstrip() for o in output]
        output_2 = '\n'.join(output_2)
        if stripped_string_compare(output_2, ground_truth):
            return True

    return False

def stripped_string_compare(s1, s2):
    s1 = s1.lstrip().rstrip()
    s2 = s2.lstrip().rstrip()
    return s1 == s2

def call_method(method, inputs):

    if isinstance(inputs, list):
        inputs = '\n'.join(inputs)

    inputs_line_iterator = iter(inputs.split('\n'))

    @patch('builtins.open', mock_open(read_data=inputs))
    @patch('sys.stdin', StringIO(inputs))
    @patch('sys.stdin.readline', lambda *args: next(inputs_line_iterator))
    @patch('sys.stdin.readlines', lambda *args: inputs.split('\n'))
    @patch('sys.stdin.read', lambda *args: inputs)

    def _inner_call_method(_method):
        try:
            return _method()
        except SystemExit:
            pass
        finally:
            pass

    return _inner_call_method(method)

def reliability_guard(maximum_memory_bytes=None):

    if maximum_memory_bytes is not None:
