def _build_optimizer(self, module):
    from verl.workers.config.optimizer import build_optimizer

    optimizer = build_optimizer(module.parameters(), self.optimizer_config)

    return optimizer

def _build_lr_scheduler(self, optimizer):
    from verl.utils.torch_functional import get_constant_schedule_with_warmup, get_cosine_schedule_with_warmup

    optim_config = self.optimizer_config

    total_steps = optim_config.total_training_steps
    num_warmup_steps = optim_config.lr_warmup_steps
    lr_scheduler_type = optim_config.lr_scheduler_type
    min_lr_ratio = optim_config.min_lr_ratio
    num_cycles = optim_config.num_cycles
    zero_indexed_step = optim_config.zero_indexed_step
    if num_warmup_steps <= 0:
        num_warmup_steps_ratio = optim_config.lr_warmup_steps_ratio
        num_warmup_steps = int(num_warmup_steps_ratio * total_steps)

    if self.rank == 0:
        print(f"Total steps: {total_steps}, num_warmup_steps: {num_warmup_steps}")

    if lr_scheduler_type == "constant":
        lr_scheduler = get_constant_schedule_with_warmup(optimizer=optimizer, num_warmup_steps=num_warmup_steps)
    elif lr_scheduler_type == "cosine":
        lr_scheduler = get_cosine_schedule_with_warmup(
            optimizer=optimizer,
            num_warmup_steps=num_warmup_steps,
            num_training_steps=total_steps,
            min_lr_ratio=min_lr_ratio,
            num_cycles=num_cycles,
            zero_indexed_step=zero_indexed_step,
        )
    else:
        raise NotImplementedError(f"LR scheduler type {lr_scheduler_type} is not supported")
    return lr_scheduler

def _apply_qat(self, module):
    """Apply QAT transformations to the model before FSDP wrapping."""
    from verl.utils.qat.core import apply_qat, enable_qat_fuse

    module = apply_qat(
        module,
        {
            "enable": self._qat_config.enable,
            "mode": self._qat_config.mode,
            "group_size": self._qat_config.group_size,
            "ignore_patterns": list(self._qat_config.ignore_patterns),
            "activation_observer": self._qat_config.activation_observer,
        },
    )
    enable_qat_fuse(module)

    if self._qat_config.mode == "w4a4":
        self._restore_w4a4_input_scales(module, self.model_config.local_path)

    return module

def _restore_w4a4_input_scales(self, model, model_path):
    """Restore input_global_scale and input_amax from checkpoint for W4A4 mode."""
    import glob

    from safetensors import safe_open

    safetensor_files = glob.glob(f"{model_path}/model*.safetensors")
    loaded_count = 0

    for sf_path in safetensor_files:
        with safe_open(sf_path, framework="pt") as f:
            for key in f.keys():
                if "input_global_scale" in key:
                    module_path = key.replace(".input_global_scale", "")
                    amax_key = f"{module_path}.input_amax"

                    module = model
                    for part in module_path.split("."):
                        module = module[int(part)] if part.isdigit() else getattr(module, part)

                    scale_val = f.get_tensor(key)
                    val = scale_val.item() if scale_val.numel() == 1 else scale_val.max().item()
                    module.input_global_scale.fill_(val)

                    amax_val = f.get_tensor(amax_key)
                    amax = amax_val.item() if amax_val.numel() == 1 else amax_val.max().item()
                    module.input_amax.fill_(amax)
                    loaded_count += 1

    logger.info(f"[QAT W4A4] Restored {loaded_count} input_global_scale/input_amax from {model_path}")

def _build_model_optimizer(self):
    from verl.utils.model import print_model_size

    # Load base model with specified configuration and dtype
    module = self._build_module()
    # Apply LoRA adapters if low-rank adaptation is enabled
    if self._is_lora:
        module = self._build_lora_module(module)

    # Apply QAT before FSDP wrapping (training only)
    if self._qat_enabled and not self.engine_config.forward_only:
        module = self._apply_qat(module)

    # Synchronize all distributed processes before proceeding
    torch.distributed.barrier()
    if self.rank == 0:
        print_model_size(module)
    log_gpu_memory_usage("After init model from HF AutoModel", logger=logger)

    # Wrap model with FSDP for distributed training (sharding, mixed precision, etc.)
    log_gpu_memory_usage("Before FSDP", logger=None)
    module = self._build_fsdp_module(module)
    log_gpu_memory_usage("After FSDP", logger=None)

    if not self.engine_config.forward_only:
        # Initialize optimizer with model parameters and config settings
        optimizer = self._build_optimizer(module)
        # Create learning rate scheduler with warmup and decay settings
        lr_scheduler = self._build_lr_scheduler(optimizer)
    else:
        optimizer = None
        lr_scheduler = None

    self.module = module
    self.optimizer = optimizer
    self.lr_scheduler = lr_scheduler

def train_mode(self, **kwargs):
    """
    Return a context manager that switches to training mode with FSDP-specific handling.

    Includes parameter and optimizer offload entry/exit.
    """
    return EngineTrainModeCtx(self, **kwargs)

def eval_mode(self, **kwargs):
    """
    Return a context manager that switches to evaluation mode with FSDP-specific handling.

    Includes activation offload entry/exit.
    """
    return EngineEvalModeCtx(self, **kwargs)

def get_data_parallel_rank(self):
    if self.ulysses_device_mesh is not None:
        return self.ulysses_device_mesh["dp"].get_local_rank()
    else:
        return torch.distributed.get_rank()

def get_data_parallel_size(self):
    return torch.distributed.get_world_size() // self.ulysses_sequence_parallel_size

def get_data_parallel_group(self):
    if self.ulysses_device_mesh is not None:
        return self.ulysses_device_mesh.get_group(mesh_dim="dp")
    else:
        return torch.distributed.group.WORLD

def get_model_parallel_group(self):
    raise NotImplementedError

def get_context_parallel_group(self):
    raise NotImplementedError

def forward_backward_batch(self, data: TensorDict, loss_function: Callable, forward_only=False) -> list[TensorDict]:
    # note that the global_batch_size should include data on all the dp
    tu.assign_non_tensor(data, sp_size=self.ulysses_sequence_parallel_size)

    # compute num_tokens in global batch for loss normalization
    batch_num_tokens = data["loss_mask"].sum().to(get_device_id())
    torch.distributed.all_reduce(
        batch_num_tokens, op=torch.distributed.ReduceOp.SUM, group=self.get_data_parallel_group()
    )
    tu.assign_non_tensor(data, batch_num_tokens=batch_num_tokens.item())
    tu.assign_non_tensor(data, dp_size=self.get_data_parallel_size())

    micro_batches, indices = prepare_micro_batches(
        data=data, dp_group=self.get_data_parallel_group(), same_micro_num_in_dp=True
    )

    output_lst = []

    ctx = torch.no_grad() if forward_only else nullcontext()

    # getattr fallback: some subclasses (e.g. VeOmniEngine) bypass FSDPEngine.__init__
    # and _build_fsdp_module, so self.scaler may not be set.
    scaler = getattr(self, "scaler", None)

    for micro_batch in micro_batches:
        with ctx:
            loss, meta_info = self.forward_step(micro_batch, loss_function=loss_function, forward_only=forward_only)

            if not forward_only:
                if scaler is not None:
                    scaler.scale(loss).backward()
                else:
                    loss.backward()
                # Training discards model_output (train_batch pops it); keeping it accumulates
                # full-length nested tensors across the mini-batch (∝ ppo_mini_batch * rollout_n) → OOM.
                meta_info.pop("model_output", None)

        output_lst.append(meta_info)

    # postprocess and return
    return postprocess_batch_func(output_lst=output_lst, indices=indices, data=data)

def forward_step(self, micro_batch: TensorDict, loss_function, forward_only):
    raise NotImplementedError("forward_step must be implemented in subclass")

def optimizer_zero_grad(self):
    """
    Zero gradients and enforce FSDP grad-clipping logic.
    """
    self.optimizer.zero_grad()

def optimizer_step(self):
    """
    Clip gradients, skip update if non-finite, and step optimizer.

    Returns:
        grad_norm (float): Norm of gradients before clipping.
    """
    assert self.optimizer_config.clip_grad is not None

    # getattr fallback: some subclasses (e.g. VeOmniEngine) bypass FSDPEngine.__init__.
    scaler = getattr(self, "scaler", None)

    # Unscale gradients before clip so the clip threshold is applied to true gradient
    # magnitudes, not scaled ones. scaler.step() will skip the update if any grad is inf/nan.
    if scaler is not None:
        scaler.unscale_(self.optimizer)

    if isinstance(self.module, FSDP):
        grad_norm = self.module.clip_grad_norm_(self.optimizer_config.clip_grad)
    elif isinstance(self.module, FSDPModule):
        grad_norm = fsdp2_clip_grad_norm_(self.module.parameters(), max_norm=self.optimizer_config.clip_grad)
    else:
        grad_norm = torch.nn.utils.clip_grad_norm_(
            self.module.parameters(), max_norm=self.optimizer_config.clip_grad
        )

    if isinstance(grad_norm, DTensor):
        grad_norm = grad_norm.full_tensor()

    if scaler is not None:
        # scaler handles inf/nan skipping internally via _check_inf_per_device.
        scaler.step(self.optimizer)
        scaler.update()
    else:
        # if grad_norm is not finite, skip the update
        if not torch.isfinite(grad_norm):
            print(f"WARN: grad_norm is not finite: {grad_norm}")
            self.optimizer.zero_grad()
        else:
            self.optimizer.step()

    if self._qat_enabled:
        from verl.utils.qat.core import invalidate_all_scales

        invalidate_all_scales(self.module)

    return grad_norm.item()

def lr_scheduler_step(self):
    """
    Advance FSDP scheduler and return updated learning rate.
    """
    self.lr_scheduler.step()
    lr = self.lr_scheduler.get_last_lr()[0]  # only return the first group
    return lr

def to(self, device: str, model: bool = True, optimizer: bool = True, grad: bool = True):
    """
    Move FSDP model and/or optimizer to CPU or GPU with offload support.
    Note that this function executes irrespective of offload config. It serves as manual control
    """
    super().to(device=device, model=model, optimizer=optimizer, grad=grad)

    if self.engine_config.forward_only:
        # force cpu_offload
        return

    device_name = get_device_name()

    assert device in (device_name, "cpu")
    if device == device_name:
        if model:
            load_fsdp_model_to_gpu(self.module)
        if optimizer and self.optimizer is not None:
            load_fsdp_optimizer(self.optimizer, device)
        gc.collect()
    elif device == "cpu":
        if model:
            offload_fsdp_model_to_cpu(self.module)
        if optimizer and self.optimizer is not None:
            offload_fsdp_optimizer(self.optimizer)

# -*- coding: utf-8 -*-
"""
Bench: during _validate, paste every sealed file under hidden/baseline onto
the workspace, then restore after validation.

Agent never sees /hidden (mounted only for GPU verify). This module only runs
inside the training process.
"""

from __future__ import annotations

import os
import shutil
import sys
from typing import Any, Dict, List, Optional


def baseline_root() -> str:
    env = (os.environ.get("BENCH_BASELINE_REWARD_ROOT") or "").strip()
    if env and os.path.isdir(env):
        return env
    if os.path.isdir("/hidden/baseline"):
        return "/hidden/baseline"
    return ""


def workspace_root() -> str:
    for cand in (
        (os.environ.get("BENCH_WORKSPACE") or "").strip(),
        "/workspace",
        os.getcwd(),
    ):
        if cand and os.path.isdir(os.path.join(cand, "verl")):
            return cand
    return os.getcwd()


def list_baseline_py_rels(root: str) -> List[str]:
    rels: List[str] = []
    if not root or not os.path.isdir(root):
        return rels
    for dirpath, _dirnames, filenames in os.walk(root):
        if "__pycache__" in dirpath.replace("\\", "/").split("/"):
            continue
        for name in filenames:
            if not name.endswith(".py"):
                continue
            full = os.path.join(dirpath, name)
            rel = os.path.relpath(full, root).replace("\\", "/")
            rels.append(rel)
    rels.sort()
    return rels


def _rel_to_modname(rel: str) -> str:
    rel = rel.replace("\\", "/").lstrip("/")
    if rel.endswith(".py"):
        rel = rel[:-3]
    return rel.replace("/", ".")


def _clear_pycache_for(path: str) -> None:
    parent = os.path.dirname(path)
    base = os.path.splitext(os.path.basename(path))[0]
    pycache = os.path.join(parent, "__pycache__")
    if not os.path.isdir(pycache):
        return
    for name in os.listdir(pycache):
        if name.startswith(base + "."):
            try:
                os.remove(os.path.join(pycache, name))
            except OSError:
                pass


def purge_modules_for_rels(rels: List[str]) -> None:
    """Drop swapped modules from sys.modules so next import reads disk."""
    targets = {_rel_to_modname(r) for r in rels}
    # Also drop importlib-sealed helpers in reward_score
    try:
        import verl.utils.reward_score as rs

        cache = getattr(rs, "_BASELINE_FN_CACHE", None)
        if isinstance(cache, dict):
            cache.clear()
    except Exception:
        pass

    to_del = []
    for name in list(sys.modules.keys()):
        if name in targets:
            to_del.append(name)
            continue
        for t in targets:
            if name.startswith(t + "."):
                to_del.append(name)
                break
    for name in to_del:
        sys.modules.pop(name, None)


def install_baseline_files(
    *,
    baseline: Optional[str] = None,
    workspace: Optional[str] = None,
) -> Dict[str, Any]:
    """
    Paste all sealed *.py under baseline onto workspace. Returns state for restore.
    """
    broot = baseline if baseline is not None else baseline_root()
    wroot = workspace if workspace is not None else workspace_root()
    state: Dict[str, Any] = {
        "ok": False,
        "baseline": broot,
        "workspace": wroot,
        "rels": [],
        "backups": {},  # rel -> original bytes or None if missing
        "installed": [],
    }
    if not broot or not os.path.isdir(broot):
        return state
    if not wroot or not os.path.isdir(wroot):
        return state

    rels = list_baseline_py_rels(broot)
    for rel in rels:
        src = os.path.join(broot, rel)
        dst = os.path.join(wroot, rel)
        if os.path.isfile(dst):
            with open(dst, "rb") as f:
                state["backups"][rel] = f.read()
        else:
            state["backups"][rel] = None
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        shutil.copy2(src, dst)
        _clear_pycache_for(dst)
        state["installed"].append(rel)

    state["rels"] = list(rels)
    state["ok"] = True
    if state["installed"]:
        print(
            f"[bench] validate: pasted {len(state['installed'])} sealed baseline "
            f"file(s) from {broot}",
            flush=True,
        )
    return state


def restore_baseline_files(state: Dict[str, Any]) -> None:
    """Restore Agent workspace files after validate."""
    if not state or not state.get("ok"):
        return
    wroot = state.get("workspace") or ""
    backups: Dict[str, Any] = state.get("backups") or {}
    restored = 0
    for rel, blob in backups.items():
        dst = os.path.join(wroot, rel)
        if blob is None:
            # sealed-only file that did not exist before: remove paste
            try:
                if os.path.isfile(dst):
                    os.remove(dst)
            except OSError:
                pass
            continue
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        with open(dst, "wb") as f:
            f.write(blob)
        _clear_pycache_for(dst)
        restored += 1
    if restored or state.get("installed"):
        print(
            f"[bench] validate: restored {restored} Agent file(s) after baseline paste",
            flush=True,
        )


def begin_baseline_validate(reward_loop_manager=None) -> Dict[str, Any]:
    """Paste sealed files + reinit reward workers to pick up baseline code."""
    state = install_baseline_files()
    state["reward_loop_manager"] = reward_loop_manager
    if not state.get("ok") or not state.get("rels"):
        return state
    purge_modules_for_rels(state["rels"])
    mgr = reward_loop_manager
    if mgr is not None and getattr(mgr, "reward_loop_workers", None):
        import ray

        ray.get(
            [
                w.reinit_reward_fn.remote(state["rels"])
                for w in mgr.reward_loop_workers
            ]
        )
    return state


def end_baseline_validate(state: Optional[Dict[str, Any]]) -> None:
    """Restore Agent files + reinit reward workers."""
    if not state:
        return
    restore_baseline_files(state)
    rels = list(state.get("rels") or [])
    if rels:
        purge_modules_for_rels(rels)
    mgr = state.get("reward_loop_manager")
    if mgr is not None and getattr(mgr, "reward_loop_workers", None):
        import ray

        try:
            ray.get([w.reinit_reward_fn.remote(rels) for w in mgr.reward_loop_workers])
        except Exception as e:
            print(f"[bench] WARN: reward worker reinit after restore failed: {e}", flush=True)

# -*- coding: utf-8 -*-
"""
Validation hooks for ray_trainer / reward_loop.

Installed from main_ppo_v0: wrap _validate with baseline
file paste, and ensure RewardLoopWorker.reinit_reward_fn exists.
"""

from __future__ import annotations

_INSTALLED = False


def install_bench_hooks() -> None:
    global _INSTALLED
    if _INSTALLED:
        return
    _install_validate_paste()
    _install_reward_reinit()
    _INSTALLED = True


def _install_validate_paste() -> None:
    try:
        from verl.trainer.ppo.ray_trainer import RayPPOTrainer
    except Exception as e:
        print(f"[bench] hooks: RayPPOTrainer unavailable: {e}", flush=True)
        return

    # Avoid double-wrap
    if getattr(RayPPOTrainer._validate, "_bench_wrapped", False):
        return

    original = RayPPOTrainer._validate

    def _validate(self, merged: bool = False):
        state = None
        try:
            from verl.utils.bench_baseline_swap import begin_baseline_validate

            state = begin_baseline_validate(
                reward_loop_manager=getattr(self, "reward_loop_manager", None)
            )
        except Exception as e:
            print(f"[bench] WARN: baseline validate paste failed: {e}", flush=True)
        try:
            return original(self, merged=merged)
        finally:
            try:
                from verl.utils.bench_baseline_swap import end_baseline_validate

                end_baseline_validate(state)
            except Exception as e:
                print(f"[bench] WARN: baseline validate restore failed: {e}", flush=True)

    _validate._bench_wrapped = True  # type: ignore[attr-defined]
    RayPPOTrainer._validate = _validate  # type: ignore[method-assign]
    print("[bench] hooks: wrapped RayPPOTrainer._validate for baseline paste", flush=True)


def _install_reward_reinit() -> None:
    try:
        from verl.experimental.reward_loop.reward_loop import RewardLoopWorker
    except Exception as e:
        print(f"[bench] hooks: RewardLoopWorker unavailable: {e}", flush=True)
        return

    if getattr(RewardLoopWorker, "_bench_reinit_installed", False):
        return

    def reinit_reward_fn(self, swapped_rels=None):
        try:
            from verl.utils.bench_baseline_swap import purge_modules_for_rels

            if swapped_rels:
                purge_modules_for_rels(list(swapped_rels))
        except Exception as e:
            print(f"[bench] purge_modules failed: {e}", flush=True)

        try:
            import importlib

            import verl.trainer.ppo.reward as reward_mod

            importlib.reload(reward_mod)
            load_fn = reward_mod.load_reward_manager
        except Exception:
            from verl.trainer.ppo.reward import load_reward_manager as load_fn

        self.reward_manager = load_fn(
            self.config,
            self.input_tokenizer,
            reward_router_address=self.reward_router_address,
            reward_model_tokenizer=self.reward_model_tokenizer,
        )
        return {"ok": True, "swapped_rels": list(swapped_rels or [])}

    RewardLoopWorker.reinit_reward_fn = reinit_reward_fn  # type: ignore[method-assign]
    RewardLoopWorker._bench_reinit_installed = True  # type: ignore[attr-defined]
    print("[bench] hooks: installed RewardLoopWorker.reinit_reward_fn", flush=True)

